import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that a date string is in YYYY-MM-DD format and is a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) return false;
  const date = new Date(`${dateStr}T00:00:00Z`);
  return date.getUTCFullYear() === Number(m[1]) &&
         date.getUTCMonth() === Number(m[2]) - 1 &&
         date.getUTCDate() === Number(m[3]);
}

/**
 * Validate that a quantity is a positive integer.
 * @param {unknown} qty
 * @returns {boolean}
 */
function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

/**
 * Create an invoice with enriched line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const enrichedLines = [];
  for (const line of lines) {
    if (!isValidQty(line.qty)) return fail('QTY_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }}
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @param {{ sku: string, qty: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!isValidQty(qty)) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((l) => ({ ...l }));
  const existingLineIndex = newLines.findIndex((l) => l.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((l, i) => i !== lineIndex);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing its status.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be in YYYY-MM-DD format.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'An invoice must have at least one line.',
  NOT_DRAFT: 'Only draft invoices can be modified.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

