1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
4	
5	test('createInvoice creates a valid draft invoice', () => {
6	  const result = createInvoice({
7	    customerId: 'C-001',
8	    issueDate: '2025-01-15',
9	    lines: [{ sku: 'DES-HOUR', qty: 3 }],
10	  });
11	  assert.equal(result.ok, true);
12	  assert.equal(result.value.customerId, 'C-001');
13	  assert.equal(result.value.issueDate, '2025-01-15');
14	  assert.equal(result.value.status, 'draft');
15	  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
16	  assert.equal(result.value.lines[0].name, 'Design work (hour)');
17	  assert.equal(result.value.lines[0].qty, 3);
18	  assert.equal(result.value.lines[0].unitPrice, 8500);
19	  assert.equal(result.value.lines[0].vatRate, 21);
20	});
21	
22	test('createInvoice handles multiple lines', () => {
23	  const result = createInvoice({
24	    customerId: 'C-003',
25	    issueDate: '2025-06-30',
26	    lines: [
27	      { sku: 'DEV-HOUR', qty: 5 },
28	      { sku: 'ICON-SET', qty: 2 },
29	      { sku: 'WORKSHOP-DAY', qty: 1 },
30	    ],
31	  });
32	  assert.equal(result.ok, true);
33	  assert.equal(result.value.lines.length, 3);
34	  assert.equal(result.value.lines[0].name, 'Development (hour)');
35	  assert.equal(result.value.lines[1].name, 'Icon set (24 icons)');
36	  assert.equal(result.value.lines[2].name, 'Brand workshop (day, VAT exempt)');
37	  assert.equal(result.value.lines[2].vatRate, 0);
38	});
39	
40	test('createInvoice rejects unknown customer', () => {
41	  const result = createInvoice({
42	    customerId: 'C-999',
43	    issueDate: '2025-01-15',
44	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
45	  });
46	  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
47	});
48	
49	test('createInvoice rejects invalid date format', () => {
