72	
73	test('createInvoice accepts valid dates including leap years', () => {
74	  const validDates = ['2024-02-29', '2025-01-01', '2099-12-31', '1970-01-01'];
75	  for (const dateStr of validDates) {
76	    const result = createInvoice({
