test('issueInvoice handles year changes correctly', () => {
  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const invoice2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const existing = ['INV-2024-0099'];
  const result2024 = issueInvoice(invoice2024, existing);
  const result2025 = issueInvoice(invoice2025, existing);

  assert.equal(result2024.value.number, 'INV-2024-0100');
  assert.equal(result2025.value.number, 'INV-2025-0001');
});

